Aquí tienes un ejemplo de la sintaxis básica en JavaScript:

```javascript
// Declaración de una variable
let nombre = "Juan";

// Declaración de una función
function saludar(nombre) {
    console.log("Hola, " + nombre + "!");
}

// genero de condicionales
if (nombre === "Juan") {
    saludar(nombre);
} else {
    console.log("No te conozco");
}

// genero de un ciclo
for (let i = 0; i < 3; i++) {
    console.log("Iteración", i);
}
```
Este ejemplo muestra variables, funciones, condicionales y ciclos.

Aquí tienes un ejemplo de implementación de promesas en JavaScript:

```javascript
function tareaAsincrona() {
    return new Promise((resolve, reject) => {
        const exito = Math.random() > 0.5;

        setTimeout(() => {
            if (exito) {
                resolve("¡Tarea completada exitosamente!");
            } else {
                reject("Hubo un error en la tarea.");
            }
        }, 1000);
    });
}

// Usar la promesa
const promesa = tareaAsincrona();

promesa
    .then(resultado => console.log("Éxito:", resultado))
    .catch(error => console.error("Error:", error));
```

