Aquí tienes un ejemplo básico de la función Ackermann en Python:

```python
def ackermann(m, n):
    if m == 0:
        return n + 1
    elif m > 0 and n == 0:
        return ackermann(m - 1, 1)
    else:
        return ackermann(m - 1, ackermann(m, n - 1))

print(ackermann(3, 4))  # salida: 125
```

Aquí tienes un ejemplo básico de la función Ackermann en JavaScript:

```javascript
function ackermann(m, n) {
    if (m === 0) {
        return n + 1;
    } else if (m > 0 && n === 0) {
        return ackermann(m - 1, 1);
    } else {
        return ackermann(m - 1, ackermann(m, n - 1));
    }
}

console.log(ackermann(3, 4));  // salida: 125
```

