Aquí tienes un ejemplo de QuickSort en JavaScript:

```javascript
function quicksort(arr) {
    if (arr.length <= 1) {
        return arr;
    }
    const pivot = arr[Math.floor(arr.length / 2)]; // Tomamos el pivote (elemento central)
    const left = arr.filter(x => x < pivot);  // Elementos menores que el pivote
    const middle = arr.filter(x => x === pivot);  // Elementos iguales al pivote
    const right = arr.filter(x => x > pivot);  // Elementos mayores que el pivote
    return [...quicksort(left), ...middle, ...quicksort(right)];
}

// Ejemplo de uso
let lista = [64, 34, 25, 12, 22, 11, 90];
console.log(quicksort(lista));
```

