def busqueda_lineal(lista, objetivo):
    for i in range(len(lista)):
        if lista[i] == objetivo:
            return i  # Retorna el índice donde se encuentra el objetivo
    return -1  # Si no se encuentra el objetivo, retorna -1

# Ejemplo de uso
