Here's an example of implementing promises in JavaScript:

```javascript
function asyncTask() {
    return new Promise((resolve, reject) => {
        const success = Math.random() > 0.5;

        setTimeout(() => {
            if (success) {
                resolve("Task successfully completed!");
            } else {
                reject("There was an error in the task.");
            }
        }, 1000);
    });
}

// Use the promise
const promise = asyncTask();

promise
    .then(result => console.log("Success:", result))
    .catch(error => console.error("Error:", error));
```

