function quicksort (arr) {
if (arr.length <= 1) {
return arr;
}
const pivot = arr [Math.floor (arr.length/2)];//We take the pivot (central element)
const left = arr.filter (x => x < pivot);//Elements smaller than the pivot
const middle = arr.filter (x => x => pivot);//Elements smaller than the pivot
const middle = arr.filter (x => x => pivot);//Elements smaller than the pivot
const middle = arr.filter (x => x => pivot);//Elements smaller than the pivot
const middle = arr.filter (x => x => pivot);//Elements smaller than the pivot
const middle = arr.filter (x => x => pivot);//Elements equal to the pivot
const right = arr.filter (x => x > pivot);//Elements greater than the pivot
return [... quicksort (left),... middle,... quicksort (right)];
}

